-- Consolidated migration: merges V1-V11 (original per-file history below) into a single baseline script.
-- Only safe to use on a database that has never applied any of V1-V11 individually --
-- an environment with flyway_schema_history rows for V1-V11 must NOT run this file (checksum/duplicate-version conflict).

-- ============================================================
-- Source: V1__create_all_currently_known_tables.sql
-- ============================================================
CREATE TABLE IF NOT EXISTS measurement_type (
    id                                  UUID PRIMARY KEY,
    measurement_type                    VARCHAR(255) NOT NULL,
    measurement_sub_type                VARCHAR(255),
    min_value                           DOUBLE PRECISION NOT NULL,                       --for sanity check
    max_value                           DOUBLE PRECISION NOT NULL,                       --for sanity check
    unit                                VARCHAR(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS profile (
    user_id                                 UUID PRIMARY KEY,
    picture                                 BYTEA,
    notification_day_summary                BOOLEAN NOT NULL,
    notification_day_summary_time           TIME,
    notification_measurement_due            BOOLEAN NOT NULL,
    notification_measurement_due_minutes    int,
    notification_no_internet                BOOLEAN NOT NULL,
    notification_no_bluetooth               BOOLEAN NOT NULL
);

-- aka device type
CREATE TABLE IF NOT EXISTS device (
    id                                  UUID PRIMARY KEY,
    name                                VARCHAR(255) NOT NULL,
    picture                             BYTEA,
    description                         VARCHAR(255) NOT NULL,
    connection_type                     VARCHAR(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS measurement (
    id                                  UUID PRIMARY KEY,
    measurement_type_id                 UUID REFERENCES measurement_type(id) NOT NULL,
    device_id                           UUID REFERENCES device(id),                                                         --can be null as we can add value manually (e.g.: height and weight)
    user_id                             UUID REFERENCES profile(user_id) NOT NULL,
    measured_at                         TIMESTAMP(6) NOT NULL,                                                  --cannot be auto generated as item can be inserted in later time
    "value"                             DOUBLE PRECISION NOT NULL,                                                          --cannot be null for correctness of data
    measurement_batch_id                VARCHAR(255),
    measurement_group_id                INTEGER                                                                          -- for blood pressure(systolic/diastolic)
);

-- one device can measure many measurement types
-- one measurement type can belong to many devices
CREATE TABLE IF NOT EXISTS device_measurement_type
(
    measurement_type_id     UUID REFERENCES measurement_type(id) NOT NULL,
    device_id               UUID REFERENCES device(id) NOT NULL,
    PRIMARY KEY(measurement_type_id, device_id)
);

-- not all devices will have API key
-- one device aka device type can have many users
-- one user can have many device types
CREATE TABLE IF NOT EXISTS device_user(
    profile_user_id         UUID REFERENCES profile(user_id) NOT NULL,
    device_id               UUID REFERENCES device(id) NOT NULL,
    api_key                 VARCHAR(255) NOT NULL,
    PRIMARY KEY(profile_user_id, device_id)
);
-- ============================================================
-- Source: V2__create_schedule_tables.sql
-- ============================================================
CREATE TABLE IF NOT EXISTS facility
(
    id          UUID PRIMARY KEY,
    name        VARCHAR(255) NOT NULL,
    description VARCHAR(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS caretaker
(
    id          UUID PRIMARY KEY,
    name        VARCHAR(255),
    facility_id UUID REFERENCES facility (id) NOT NULL
);

CREATE TABLE IF NOT EXISTS schedule
(
    id           UUID PRIMARY KEY,
    name         VARCHAR(255)                   NOT NULL,
    description  VARCHAR(255)                   NOT NULL,
    caretaker_id UUID REFERENCES caretaker (id) NOT NULL,
    facility_id  UUID REFERENCES facility (id)  NOT NULL,
    active       BOOLEAN                        NOT NULL
);

CREATE TABLE IF NOT EXISTS schedule_entry
(
    id                    UUID PRIMARY KEY,
    measurement_type_id   UUID REFERENCES measurement_type (id),
    scheduled_at          TIMESTAMP(6) NOT NULL,
    scheduled_mode        VARCHAR(255) NOT NULL CHECK (scheduled_mode IN ('ONCE_A_DAY', 'AT_SPECIFIC_HOUR')),
    measurement_mode      VARCHAR(255) NOT NULL CHECK (measurement_mode IN ('SINGLE', 'BATCH', 'CONTINUOUS')),
    description           VARCHAR(255),
    measurements_in_batch INTEGER
);

CREATE TABLE IF NOT EXISTS schedule_user
(
    schedule_id UUID REFERENCES schedule (id)     NOT NULL,
    user_id     UUID REFERENCES profile (user_id) NOT NULL,
    PRIMARY KEY (schedule_id, user_id)
);

CREATE TABLE IF NOT EXISTS schedule_entry_schedule
(
    schedule_id       UUID REFERENCES schedule (id)       NOT NULL,
    schedule_entry_id UUID REFERENCES schedule_entry (id) NOT NULL,
    PRIMARY KEY (schedule_id, schedule_entry_id)
);
-- ============================================================
-- Source: V3__create_mobile_token_table.sql
-- ============================================================
CREATE TABLE IF NOT EXISTS mobile_token (
    token       VARCHAR(255) PRIMARY KEY,
    user_id     UUID REFERENCES profile(user_id) NOT NULL
);
