-- Source: V5__alter_measurement_schedule_entry.sql
-- ============================================================
ALTER TABLE measurement ADD COLUMN measurement_mode VARCHAR(255) NOT NULL CHECK (measurement_mode IN ('SINGLE', 'BATCH', 'CONTINUOUS')); -- Value is an equivalent of the same value in the schedule_entry table

ALTER TABLE schedule_entry ADD COLUMN interval_minutes INTEGER; -- Value represents a time duration of continuous measurement in minutes


-- ============================================================
-- Source: V6__task_queue.sql
-- ============================================================
CREATE TABLE IF NOT EXISTS task_queue (
  id UUID PRIMARY KEY,
  user_id UUID REFERENCES profile (user_id) NOT NULL,
  device_id UUID REFERENCES device (id) NOT NULL,
  measurement_type_id UUID REFERENCES measurement_type (id) NOT NULL,
  start_time TIMESTAMP(6) NOT NULL,
  end_time TIMESTAMP(6) NOT NULL,
  status VARCHAR(255) NOT NULL,
  retry_count INTEGER NOT NULL,
  created_at TIMESTAMP(6) NOT NULL,
  retry_at TIMESTAMP(6)
);

